#!/usr/bin/env python3
"""
make_art.py - generates ../include/art.h (the pixel font). The faces themselves are
drawn in code by include/face.h, so they can morph smoothly between expressions.
"""
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import font  # noqa: E402

L = [
    "// art.h - GENERATED by tools/make_art.py - do not edit by hand.",
    "#pragma once",
    "#include <stdint.h>",
    "",
    "struct Sprite { uint16_t w, h; const uint8_t* px; const uint16_t* pal; };",
    "struct Glyph  { uint8_t w; uint8_t rows[8]; };",
    "",
    "static const Glyph FONT[128] = {",
]
glyphs = {code: (w, bits) for code, w, bits in font.glyph_table()}
for code in range(128):
    w, bits = glyphs.get(code, (0, [0] * 8))
    L.append("  {%d,{%s}}," % (w, ",".join(map(str, bits))))
L.append("};")
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "include", "art.h")
with open(out, "w") as f:
    f.write("\n".join(L) + "\n")
print("wrote", os.path.normpath(out))
